#!/usr/bin/env node
/**
 * plugin-pack: signs a plugin folder (writes signature.json) and optionally packs it as a zip archive
 * ready for import in the admin console.
 *
 *   node scripts/plugin-pack.mjs <plugin-dir> [--key <key.json>] [--zip <out.zip>]
 *   node scripts/plugin-pack.mjs --all          # sign every plugin under plugins/
 *
 * The signing key defaults to conf/plugin-dev-key.json, the local development key generated by
 * scripts/plugin-dev-setup.mjs (gitignored, DEMO ONLY, never committed). The matching public keys live in
 * conf/plugin-trust.json (also generated, also gitignored); the loader (apps/api/src/plugins/v1/loader.ts)
 * verifies the signature before registering a plugin that declares `security.signed` or ships handlers.
 */
import { createHash, sign, createPrivateKey } from 'node:crypto';
import { readFileSync, writeFileSync, readdirSync, statSync, existsSync, renameSync } from 'node:fs';
import { join, resolve, relative } from 'node:path';
import { deflateRawSync } from 'node:zlib';

function canonical(v) {
  if (Array.isArray(v)) return `[${v.map(canonical).join(',')}]`;
  if (v && typeof v === 'object') return `{${Object.keys(v).sort().map((k) => `${JSON.stringify(k)}:${canonical(v[k])}`).join(',')}}`;
  return JSON.stringify(v);
}

function filesOf(dir, base = dir) {
  const out = [];
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.name === 'signature.json' || e.name.startsWith('.')) continue;
    const p = join(dir, e.name);
    if (e.isDirectory()) out.push(...filesOf(p, base));
    else out.push(relative(base, p));
  }
  return out.sort();
}

export function signPlugin(dir, privateKeys) {
  const manifest = JSON.parse(readFileSync(join(dir, 'manifest.json'), 'utf8'));
  const files = {};
  for (const f of filesOf(dir)) files[f] = createHash('sha256').update(readFileSync(join(dir, f))).digest('hex');
  const key = privateKeys[manifest.publisher];
  if (!key) throw new Error(`no signing key for publisher ${manifest.publisher}`);
  const body = { alg: 'ed25519', publisher: manifest.publisher, files };
  const signature = sign(null, Buffer.from(canonical(body)), createPrivateKey({ key: Buffer.from(key, 'base64'), format: 'der', type: 'pkcs8' })).toString('base64');
  writeFileSync(join(dir, 'signature.json'), JSON.stringify({ ...body, signature }, null, 2) + '\n');
  return { id: manifest.id, files: Object.keys(files).length };
}

/** Minimal zip writer (stored entries): enough for the signed-archive import of plan step 8. */
export function packZip(dir, out) {
  const files = filesOf(dir).concat('signature.json');
  const parts = [], central = [];
  let offset = 0;
  for (const f of files) {
    const data = readFileSync(join(dir, f));
    const crc = crc32(data);
    const name = Buffer.from(f);
    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); local.writeUInt16LE(20, 4); local.writeUInt16LE(0, 6); local.writeUInt16LE(0, 8);
    local.writeUInt16LE(0, 10); local.writeUInt16LE(0, 12); local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(data.length, 18); local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(name.length, 26); local.writeUInt16LE(0, 28);
    parts.push(local, name, data);
    const c = Buffer.alloc(46);
    c.writeUInt32LE(0x02014b50, 0); c.writeUInt16LE(20, 4); c.writeUInt16LE(20, 6); c.writeUInt16LE(0, 8); c.writeUInt16LE(0, 10);
    c.writeUInt16LE(0, 12); c.writeUInt16LE(0, 14); c.writeUInt32LE(crc, 16); c.writeUInt32LE(data.length, 20); c.writeUInt32LE(data.length, 24);
    c.writeUInt16LE(name.length, 28); c.writeUInt16LE(0, 30); c.writeUInt16LE(0, 32); c.writeUInt16LE(0, 34); c.writeUInt16LE(0, 36);
    c.writeUInt32LE(0, 38); c.writeUInt32LE(offset, 42);
    central.push(c, name);
    offset += 30 + name.length + data.length;
  }
  const cd = Buffer.concat(central);
  const end = Buffer.alloc(22);
  end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(0, 4); end.writeUInt16LE(0, 6);
  end.writeUInt16LE(files.length, 8); end.writeUInt16LE(files.length, 10);
  end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(offset, 16); end.writeUInt16LE(0, 20);
  writeFileSync(out, Buffer.concat([...parts, cd, end]));
  return out;
}
let CRC_TABLE;
function crc32(buf) {
  if (!CRC_TABLE) { CRC_TABLE = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; CRC_TABLE[n] = c >>> 0; } }
  let c = 0xffffffff;
  for (const b of buf) c = CRC_TABLE[(c ^ b) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}

if (process.argv[1] && process.argv[1].endsWith('plugin-pack.mjs')) {
  const args = process.argv.slice(2);
  const root = resolve(new URL('..', import.meta.url).pathname);
  const keyPath = args.includes('--key') ? resolve(args[args.indexOf('--key') + 1]) : join(root, 'conf', 'plugin-dev-key.json');
  const keys = JSON.parse(readFileSync(keyPath, 'utf8'));
  delete keys._comment;
  if (args[0] === '--all') {
    for (const e of readdirSync(join(root, 'plugins'), { withFileTypes: true })) {
      if (!e.isDirectory() || e.name.startsWith('.') || e.name.startsWith('_') || e.name === 'examples') continue;
      if (!existsSync(join(root, 'plugins', e.name, 'manifest.json'))) continue;
      const r = signPlugin(join(root, 'plugins', e.name), keys);
      console.log(`signed ${r.id} (${r.files} files)`);
    }
  } else {
    const dir = resolve(args[0]);
    const r = signPlugin(dir, keys);
    console.log(`signed ${r.id} (${r.files} files)`);
    if (args.includes('--zip')) {
      const out = resolve(args[args.indexOf('--zip') + 1]);
      packZip(dir, out);
      console.log(`packed ${out}`);
    }
  }
}
